const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const pointCuyuni = ee.Geometry.Point(-58.628264, 6.437929);
  const pointMazaEsse = ee.Geometry.Point(-58.606792, 6.407305);
  const date = '2023-08-16';
  const scale = 10; // Sentinel-2 resolution is 10m for visible bands
  const buffer_m = 30; // 30-meter buffer around the points to sample river area

  const roiCuyuni = pointCuyuni.buffer(buffer_m);
  const roiMazaEsse = pointMazaEsse.buffer(buffer_m);

  // Function to mask clouds from Sentinel-2 SR data.
  // Uses the QA60 band for cloud detection.
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000) // Scale to surface reflectance [0, 1]
                .select(['B2', 'B3', 'B4', 'B8']); // Select relevant bands
  }

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filter(ee.Filter.or(
      ee.Filter.bounds(roiCuyuni),
      ee.Filter.bounds(roiMazaEsse)
    ))
    .map(maskS2clouds);

  const imageCount = await collection.size().getInfo();

  if (imageCount === 0) {
    console.log("No Sentinel-2 images found for the specified date and location.");
    console.log("C1");
    return;
  }

  // Take the first image as there should be only one for a specific day/location,
  // or a median if multiple images exist (e.g., across tile boundaries).
  const image = collection.mosaic(); // Use mosaic to combine potentially overlapping images

  // Bands B2 (Blue), B3 (Green), B4 (Red) determine visible color.
  // We'll use the Green band (B3) as a general proxy for 'lightness' in water.
  // Higher reflectance in B3 generally means lighter/greener water.

  // 3. Processing (Calculate pixel count and mean reflectance)
  const bandToMeasure = 'B3'; // Green band for lightness

  const reduceRegionParams = {
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    scale: scale,
    maxPixels: 1e9
  };

  let statsCuyuni = await image.select(bandToMeasure).reduceRegion({
    ...reduceRegionParams,
    geometry: roiCuyuni
  }).getInfo();

  let statsMazaEsse = await image.select(bandToMeasure).reduceRegion({
    ...reduceRegionParams,
    geometry: roiMazaEsse
  }).getInfo();

  const meanCuyuni = statsCuyuni ? statsCuyuni[bandToMeasure + '_mean'] : null;
  const countCuyuni = statsCuyuni ? statsCuyuni[bandToMeasure + '_count'] : 0;
  const meanMazaEsse = statsMazaEsse ? statsMazaEsse[bandToMeasure + '_mean'] : null;
  const countMazaEsse = statsMazaEsse ? statsMazaEsse[bandToMeasure + '_count'] : 0;

  // 4. Validation and check for C2 & C3
  if (countCuyuni === 0 || countMazaEsse === 0) {
    console.log(`Cuyuni Pixels: ${countCuyuni}, Mazaruni/Essequibo Pixels: ${countMazaEsse}`);
    console.log("No valid pixels remain after cloud masking/buffering for one or both locations.");
    console.log("C2");
    return;
  }

  if (meanCuyuni === null || isNaN(meanCuyuni) || meanMazaEsse === null || isNaN(meanMazaEsse)) {
    console.log("Calculation failed: Received null or NaN for mean reflectance.");
    console.log(`Cuyuni Mean B3: ${meanCuyuni}, Mazaruni/Essequibo Mean B3: ${meanMazaEsse}`);
    console.log("C3");
    return;
  }

  // 5. Comparison and Final Answer
  console.log(`Image date: ${date}`);
  console.log(`Cuyuni River (Green Band B3 Reflectance): ${meanCuyuni.toFixed(4)} (Pixels: ${countCuyuni})`);
  console.log(`Mazaruni/Essequibo Rivers (Green Band B3 Reflectance): ${meanMazaEsse.toFixed(4)} (Pixels: ${countMazaEsse})`);

  // "Lighter in color" implies higher reflectance value.
  if (meanCuyuni > meanMazaEsse) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
